function help(){const categories=['All topics','Getting Started','Understand Costs','Pricing & Profit','Sales & Growth','Reports','Troubleshooting'];return `<section class="card"><h2>Business Learning & Support Center</h2><p>Learn as you go. Each guide explains what to do, shows an example, and warns you about common mistakes.</p><label>What do you need help with?<input id="helpQuery" placeholder="Try: service, price, profit, report, save"></label><label>Browse topics<select id="helpCategory">${categories.map(x=>`<option>${x}</option>`).join('')}</select></label></section><section class="card" id="helpResults">${helpResults('','All topics')}</section><section class="card"><h3>Quick definitions</h3>${topics.map(x=>`<details><summary>${esc(x[0])}</summary><p>${esc(x[1])}</p></details>`).join('')}</section>`}
function helpResults(q,category='All topics'){const list=learning.filter(x=>(category==='All topics'||x.category===category)&&(x.title+' '+x.intro+' '+x.example+' '+x.steps.join(' ')).toLowerCase().includes(q.toLowerCase()));return list.map(x=>`<details class="lesson"><summary>${esc(x.title)} <small>· ${esc(x.category)}</small></summary><p>${esc(x.intro)}</p><h4>Follow these steps</h4><ol>${x.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p><strong>Example:</strong> ${esc(x.example)}</p><p class="notice warning"><strong>Watch out:</strong> ${esc(x.mistake)}</p></details>`).join('')||'<p>No matching guide. Try a different word or choose All topics.</p>'}
const helpByField={
 activityType:['Business activity','Choose the type of work for this particular calculation. A mixed business can save different types of activities.'],saleUnit:['Completed sale or delivery','Use the word you use in your business: item, meal, appointment, job, project, participant, or another unit.'],wastePercent:['Waste allowance','If some supplies are lost or spoiled, this percentage increases the cost of the supplies needed to produce the usable output.'],overhead:['Share of overhead','Enter only the portion of recurring business costs that belongs to this activity. Do not include it again in other costs.'],healthFixed:['Monthly fixed expenses','Regular expenses you must cover regardless of how many sales you make. Avoid counting expenses already included in your per-sale cost.'],healthGoal:['Monthly earnings goal','An additional amount you hope to earn after the costs included in this estimate.'],healthCapacity:['Monthly capacity','The number of items, jobs, appointments, or places you can realistically sell or deliver in one month.'],
 biz:['Business name','The name you want to appear on your saved reports.'],stage:['Business stage','Choose where you are today. This helps us tailor explanations; it does not limit the tools you can use.'],currency:['Currency','Choose the currency you use for prices and costs. Changing it does not convert previously entered amounts using exchange rates.'],brand:['Report brand color','Choose a color for headings and accents in your printable reports.'],name:['Name of this work','Use a name you will recognize later, such as Wedding Cake, Lawn Mowing, or Tax Preparation.'],yield:['How many are included?','Enter the number of items, portions, appointments, jobs, seats or completed units covered by this calculation. For one job or appointment, enter 1.'],price:['Selling price','What a customer will pay for one item, appointment, project, serving or other unit.'],hours:['Time spent','Include preparation, the work itself, cleanup and other time needed to deliver this activity.'],rate:['Hourly labor cost','What one hour of work should cost your business. If you work yourself, include a reasonable value for your time.'],other:['Other costs','Include relevant costs not entered above, such as delivery, equipment use, selling fees or an appropriate share of overhead. Avoid counting the same cost twice.'],margin:['Target gross margin','The percentage of the selling price remaining after the costs included in this calculation. It is not necessarily take-home pay.'],selected:['Saved activity','Choose a product, service, recipe, job or other activity you previously saved in Cost.'],decision:['Type of offer','Choose the kind of sales decision you want to test. The toolkit compares the offer with your saved costs.'],costChange:['Cost change','Try an increase or decrease in the cost per completed unit. For example, enter 10 if costs might rise 10%.'],priceChange:['Price change','Try raising or lowering your selling price without changing your original saved record.'],volume:['Sales quantity','How many items, appointments, projects or other units do you expect to sell in this scenario?'],reportType:['Report type','Choose a costing, pricing, offer, planning or combined summary report. Each report is generated separately.'],reportRecord:['Saved report information','Choose the specific saved activity or decision to include in this report.']
};
const helpByData={buyQty:'How much did you buy in total? For example, a 1 kg bag or a pack of 50.',buyUnit:'Select the measurement used when you bought it. Weight and volume cannot be mixed automatically.',paid:'Enter the total amount you paid for that purchase.',used:'How much of the purchase will this activity use?',useUnit:'Select the unit used in this activity. It must be compatible with the purchase unit.'};
function addInlineHelp(){const scope=$('#app');if(!scope)return;scope.querySelectorAll('input,select').forEach(el=>{if(el.type==='hidden'||el.type==='checkbox'||el.type==='file'||el.type==='color'||el.id==='helpQuery'||el.id==='helpCategory')return;const info=helpByField[el.id]||(el.dataset.k&&helpByData[el.dataset.k]?[el.dataset.k,helpByData[el.dataset.k]]:null);if(!info)return;const label=el.closest('label');if(!label||label.querySelector('.help-toggle'))return;const btn=document.createElement('button');btn.type='button';btn.className='help-toggle';btn.setAttribute('aria-label','Explain '+(label.textContent||info[0]).trim());btn.setAttribute('aria-expanded','false');btn.textContent='?';const details=document.createElement('span');details.className='field-explanation';details.hidden=true;details.textContent=info[1];btn.addEventListener('click',()=>{details.hidden=!details.hidden;btn.setAttribute('aria-expanded',String(!details.hidden))});el.before(btn);el.after(details)})}
// Portable, versioned export. This is a future import contract, not a live FyscalOS integration.
function portableExport(){
 const copy=value=>JSON.parse(JSON.stringify(value));
 return {format:'fyscalos-toolkit-transfer',schemaVersion:1,source:'The Business Numbers Toolkit',exportedAt:new Date().toISOString(),
  currency:state.profile.currency||'USD',
  business:copy(state.profile),
  activities:copy(state.records),
  pricingDecisions:copy(state.prices),
  sellingDecisions:copy(state.offers),
  planningScenarios:copy(state.scenarios),customCostCategories:copy(state.customCategories),monthlyFixedCosts:state.monthlyFixedCosts,monthlyGoal:state.monthlyGoal,
  notes:{costing:'Estimates based on user-entered costs, not accounting transactions.',financials:'No actual income, expenses, bank balances, or tax records are included.',integration:'Future FyscalOS import requires a compatible importer; no account sync is currently available.'}};
}
function downloadJson(data,filename){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function settings(){return `<section class="card"><h2>Appearance</h2><label>Accent color<input type="color" id="theme" value="${esc(state.theme)}"></label><button class="primary" id="saveTheme">Apply Theme</button><div id="themeStatus"></div></section><section class="card"><h2>Data Management</h2><p>Saved data stays in this browser on this device. Download backups regularly. Private browsing or cleared site data can erase local records.</p><div class="row"><button class="primary" id="backup">Download Backup</button><label>Restore JSON backup<input type="file" id="restore" accept=".json,application/json"></label><button class="secondary" id="reset">Delete Saved Data</button></div><div id="settingsStatus"></div><div class="row"><button class="secondary" id="storageCheck">Check Local Database</button><button class="secondary" id="recoverDB">Recover Local Database</button></div><p class="muted">Recovery will ask before replacing current data. Keep a downloaded backup on a separate device.</p></section><section class="card"><h2>Take your business numbers with you</h2><p>When you're ready for more detailed financial management, FyscalOS™ is the next step. Your toolkit works independently—you do not need FyscalOS™ to use it.</p><p>Download a structured copy of your business setup, saved activities, prices, offers, and plans. This file is for future transfer; it does not connect to or import into FyscalOS™ today.</p><button class="secondary" id="portableExport">Download My Business Data</button><div id="exportStatus"></div><label>Import Toolkit transfer file<input type="file" id="transferImport" accept=".json,application/json"></label><p class="muted">Keep this file private. It may contain commercially sensitive information. No data is sent to a server by this button.</p></section>`}
function history(items,describe){return items.length?items.slice().reverse().map(x=>`<div class="saved-item"><span>${esc(describe(x))}</span><small>${esc(x.date||'')}</small></div>`).join(''):'<p>No saved decisions yet.</p>'}
function health(){return `<section class="card"><h2>Business Health & Sales Targets</h2><p>Use your saved cost estimates to explore how many sales you may need. This is a planning estimate, not a record of actual business income.</p><label>Choose saved activity<select id="selected">${recordOptions()}</select></label><label>Monthly fixed expenses<input id="healthFixed" type="number" min="0" step="any" value="${esc(state.monthlyFixedCosts||0)}"></label><label>Extra earnings goal per month<input id="healthGoal" type="number" min="0" step="any" value="${esc(state.monthlyGoal||0)}"></label><label>Expected sales you can complete each month<input id="healthCapacity" type="number" min="1" step="1" value="40"></label><button class="primary" id="runHealth">Check My Business Numbers</button><div id="healthOutput" aria-live="polite"></div></section>`}
const views={Home:home,'My Business':business,Cost:cost,Price:price,Sell:sell,Plan:plan,Reports:reports,'Business Health':health,Help:help,Settings:settings};
function render(){document.documentElement.style.setProperty('--accent',state.theme||'#245b4a');$('#nav').innerHTML=pages.map(p=>`<button type="button" data-page="${p}" class="${page===p?'active':''}">${p}</button>`).join('');$('#app').innerHTML=(storageError?alert(storageError,'error'):'')+views[page]();$$('#nav button').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});wire();addInlineHelp()}
function collect(type){return $$('.cost-row.'+type).map(el=>Object.fromEntries($$in(el,'[data-k]').map(f=>[f.dataset.k,f.value]))).filter(r=>[r.name,r.buyQty,r.paid,r.used].some(v=>String(v||'').trim()!==''))}
const $$in=(el,s)=>[...el.querySelectorAll(s)];
function message(id,text,kind='ok'){const el=$(id);if(el)el.innerHTML=alert(text,kind)}
function saveItem(list,item){list.push(item);if(!save()){list.pop();return false}return true}
function requireProduct(){let r=chosen();if(!r)throw Error(state.records.length?'Select a saved product first.':'No saved products yet. Go to Cost and save a product first.');return r}
function showResult(html){$('#output').innerHTML=html}
function saveDecisionButton(kind,payload){const el=$('#saveDecision');if(!el)return;el.onclick=()=>{const ok=saveItem(state[kind],{id:uid(),date:new Date().toLocaleDateString(),...payload});message('#decisionStatus',ok?'Decision saved and verified.':storageError,ok?'ok':'error');if(ok){el.disabled=true;el.textContent='Saved'}}}
function sellFields(){const d=$('#decision').value;$('#sellFields').innerHTML=({discount:'<label>Discount percentage<input id="offer" type="number" value="10" step="any"></label>',wholesale:'<label>Wholesale price per unit<input id="offer" type="number" step="any"></label><label>Order quantity<input id="qty" type="number" min="1" value="12"></label>',budget:'<label>Customer budget per unit<input id="offer" type="number" step="any"></label>',shipping:'<label>Shipping cost absorbed per order<input id="offer" type="number" step="any"></label><label>Units in order<input id="qty" type="number" min="1" value="1"></label>',fee:'<label>Fee percentage<input id="offer" type="number" value="3" step="any"></label>',promotion:'<label>Special offer price per unit<input id="offer" type="number" step="any"></label>'})[d]}
function wire(){
$('#saveBiz')?.addEventListener('click',()=>{const previous=structuredClone(state.profile);state.profile={...state.profile,name:$('#biz').value.trim(),stage:$('#stage').value,currency:$('#currency').value,brand:$('#brand').value};if(!save()){state.profile=previous;message('#bizStatus',storageError,'error')}else message('#bizStatus','Profile saved and verified on this device.')});
$('#saveExperience')?.addEventListener('click',()=>{const prev=state.experience;state.experience=$('#experience').value;if(!save()){state.experience=prev;message('#experienceStatus',storageError,'error')}else message('#experienceStatus','Experience saved. All records and tools are preserved.')});
$('#saveCategories')?.addEventListener('click',()=>{const old=state.customCategories;state.customCategories=[...new Set($('#customCategoryNames').value.split(',').map(x=>x.trim()).filter(Boolean))];if(!save()){state.customCategories=old;message('#categoryStatus',storageError,'error')}else message('#categoryStatus','Custom cost categories saved.')});
$('#saveGoals')?.addEventListener('click',()=>{const fixed=number($('#fixedCosts').value),goal=number($('#monthlyGoal').value);if(!Number.isFinite(fixed)||fixed<0||!Number.isFinite(goal)||goal<0)return message('#goalStatus','Enter valid nonnegative amounts.','error');const prev=[state.monthlyFixedCosts,state.monthlyGoal];state.monthlyFixedCosts=fixed;state.monthlyGoal=goal;if(!save()){[state.monthlyFixedCosts,state.monthlyGoal]=prev;message('#goalStatus',storageError,'error')}else message('#goalStatus','Monthly goals saved.')});
$('#activityType')?.addEventListener('change',()=>{const t=ToolkitTemplateFor($('#activityType').value,state.customCategories);$('#industryHint').textContent=t.prompt+' Suggested costs: '+t.categories.join(', ');$('#saleUnit').value=t.unit});
$('#addCustom')?.addEventListener('click',()=>{$('#customCosts').insertAdjacentHTML('beforeend',customLine($$('.custom-cost-row').length));addInlineHelp()});
$('#customCosts')?.addEventListener('click',e=>{if(e.target.matches('.removeCustom'))e.target.closest('.custom-cost-row').remove()});
$('#runHealth')?.addEventListener('click',()=>{try{const r=requireProduct(),c=calculate(r),fixed=number($('#healthFixed').value),goal=number($('#healthGoal').value),capacity=number($('#healthCapacity').value);if([fixed,goal,capacity].some(x=>!Number.isFinite(x)||x<0)||capacity<1)throw Error('Enter valid nonnegative amounts and capacity above zero.');const variable=c.unit,contribution=number(r.price)-variable,breakEven=ToolkitEngine.breakEven({price:r.price,variableCost:variable,fixedCosts:fixed}),target=ToolkitEngine.salesTarget({price:r.price,variableCost:variable,fixedCosts:fixed,goal});$('#healthOutput').innerHTML=`<div class="grid">${metric('Money left after included cost per '+esc(r.saleUnit||'sale'),fmt(contribution))}${metric('Sales to cover monthly fixed expenses',breakEven===null?'Not possible at this price':breakEven)}${metric('Sales to cover expenses and goal',target===null?'Not possible at this price':target)}${metric('Estimated amount at your capacity',fmt(contribution*capacity-fixed))}</div>${alert('Check that monthly fixed expenses are not already included in your per-sale costs; otherwise they would be counted twice. This is a forecast, not actual profit.','warning')}`;}catch(e){message('#healthOutput',e.message,'error')}});
$('#saveTemplates')?.addEventListener('click',()=>{const prev=state.profile.templates;state.profile.templates=$$('.tpl:checked').map(x=>x.value);if(!save()){state.profile.templates=prev;message('#tplStatus',storageError,'error')}else message('#tplStatus','Business types saved.')});
$('#addM')?.addEventListener('click',()=>{$('#materials').insertAdjacentHTML('beforeend',line('material',$$('.material').length));addInlineHelp()});
$('#addP')?.addEventListener('click',()=>{$('#packaging').insertAdjacentHTML('beforeend',line('package',$$('.package').length));addInlineHelp()});
$('#app').querySelectorAll('.removeLine').forEach(b=>b.onclick=()=>b.closest('.cost-row').remove());
$('#calculate')?.addEventListener('click',()=>{try{const r={id:editingId||uid(),name:$('#name').value.trim(),yield:number($('#yield').value),price:number($('#price').value||0),hours:number($('#hours').value||0),rate:number($('#rate').value||0),other:number($('#other').value||0),materials:collect('material'),packaging:collect('package'),activityType:$('#activityType').value,saleUnit:$('#saleUnit').value.trim()||'unit',customCosts:customCostRows(),wastePercent:number($('#wastePercent').value||0),overhead:number($('#overhead').value||0)};if(!r.name)throw Error('Give this work a name.');if(!Number.isFinite(r.yield)||r.yield<=0)throw Error('Enter a valid batch yield greater than zero.');if([r.price,r.hours,r.rate,r.other].some(v=>!Number.isFinite(v)||v<0))throw Error('Price, labor and other costs must be valid nonnegative numbers.');if(!r.materials.length&&!r.packaging.length&&!r.customCosts.length&&r.hours===0&&r.other===0&&r.overhead===0)throw Error('Enter at least one material, packaging, labor or other cost.');const c=calculate(r),old=state.records.slice(),index=state.records.findIndex(x=>x.id===r.id);if(index>=0)state.records[index]=r;else state.records.push(r);if(!save()){state.records=old;throw Error(storageError)}editingId=null;$('#costResult').innerHTML=alert('Product saved and verified. It is now available in Price, Sell, Plan and Reports.')+`<div class="grid">${metric('Batch cost',fmt(c.total))}${metric('Unit cost',fmt(c.unit))}${metric('Amount remaining/unit',fmt(c.remaining))}${metric('Gross margin',c.margin.toFixed(1)+'%')}</div>`;$('#calculate').disabled=true;$('#calculate').textContent='Saved';}catch(e){message('#costResult',e.message,'error')}});
$$('.editRecord').forEach(b=>b.onclick=()=>{editingId=b.dataset.id;render();window.scrollTo(0,0)});
$$('.deleteRecord').forEach(b=>b.onclick=()=>{const r=state.records.find(x=>x.id===b.dataset.id);if(!r||!confirm(`Delete ${r.name}? This does not delete previously saved decisions.`))return;const old=state.records.slice();state.records=state.records.filter(x=>x.id!==r.id);if(!save()){state.records=old;alert(storageError)}render()});
$('#cancelEdit')?.addEventListener('click',()=>{editingId=null;render()});
$('#runPrice')?.addEventListener('click',()=>{try{const r=requireProduct(),m=number($('#margin').value);if(!Number.isFinite(m)||m<0||m>=100)throw Error('Enter a target margin from 0 to less than 100%.');const c=calculate(r),target=c.unit/(1-m/100);showResult(`<div class="grid">${metric('Recorded unit cost',fmt(c.unit))}${metric('Target selling price',fmt(target))}${metric('Current selling price',fmt(r.price))}${metric('Current gross margin',c.margin.toFixed(1)+'%')}</div><p class="muted">Based on entered costs, not guaranteed take-home income.</p><button class="primary" id="saveDecision">Save Pricing Decision</button><div id="decisionStatus"></div>`);saveDecisionButton('prices',{recordId:r.id,productName:r.name,margin:m,target,regularPrice:r.price})}catch(e){showResult(alert(e.message,'error'))}});
$('#decision')?.addEventListener('change',sellFields);if($('#sellFields'))sellFields();
$('#runSell')?.addEventListener('click',()=>{try{const r=requireProduct(),d=$('#decision').value,v=number($('#offer').value),qty=number($('#qty')?.value||1),c=calculate(r);if(!Number.isFinite(v)||v<0||!Number.isInteger(qty)||qty<1)throw Error('Enter a valid offer and order quantity.');if(['discount','fee'].includes(d)&&v>100)throw Error('Percentage cannot exceed 100%.');let p=n(r.price),fee=0;if(d==='discount')p*=1-v/100;if(['wholesale','budget','promotion'].includes(d))p=v;if(d==='shipping')fee=v/qty;if(d==='fee')fee=p*v/100;const remaining=p-c.unit-fee,margin=p>0?remaining/p*100:0;showResult(`<div class="grid">${metric('Customer pays/unit',fmt(p))}${metric('Recorded cost/unit',fmt(c.unit))}${metric('Additional offer cost/unit',fmt(fee))}${metric('Amount remaining/unit',fmt(remaining))}${metric('Margin after offer',margin.toFixed(1)+'%')}${metric('Order amount remaining',fmt(remaining*qty))}</div>${alert(remaining<0?'This offer does not cover entered costs.':'Check any costs not included in your product record.',remaining<0?'error':'warning')}<button class="primary" id="saveDecision">Save Selling Decision</button><div id="decisionStatus"></div>`);saveDecisionButton('offers',{recordId:r.id,productName:r.name,decision:d,offer:v,qty,customerPrice:p,remaining,margin})}catch(e){showResult(alert(e.message,'error'))}});
$('#runPlan')?.addEventListener('click',()=>{try{const r=requireProduct(),cc=number($('#costChange').value),pc=number($('#priceChange').value),volume=number($('#volume').value),c=calculate(r);if(!Number.isFinite(cc)||cc< -100||!Number.isFinite(pc)||pc< -100||!Number.isInteger(volume)||volume<1)throw Error('Enter valid percentage changes and a whole-number quantity of at least 1.');const nextCost=c.unit*(1+cc/100),nextPrice=n(r.price)*(1+pc/100),current=(n(r.price)-c.unit)*volume,next=(nextPrice-nextCost)*volume,difference=next-current;showResult(`<div class="table-wrap"><table><tr><th></th><th>Current</th><th>Scenario</th><th>Difference</th></tr><tr><td>Unit cost</td><td>${fmt(c.unit)}</td><td>${fmt(nextCost)}</td><td>${fmt(nextCost-c.unit)}</td></tr><tr><td>Unit price</td><td>${fmt(r.price)}</td><td>${fmt(nextPrice)}</td><td>${fmt(nextPrice-n(r.price))}</td></tr><tr><td>Amount remaining × ${volume}</td><td>${fmt(current)}</td><td>${fmt(next)}</td><td>${fmt(difference)}</td></tr></table></div>${alert('Scenario only. Your original product is unchanged.')}<button class="primary" id="saveDecision">Save Scenario</button><div id="decisionStatus"></div>`);saveDecisionButton('scenarios',{recordId:r.id,productName:r.name,costChange:cc,priceChange:pc,volume,current,next,difference})}catch(e){showResult(alert(e.message,'error'))}});
$('#reportType')?.addEventListener('change',()=>{reportChoices();showResult('')});if($('#reportType'))reportChoices();
$('#runReport')?.addEventListener('click',()=>{try{const type=$('#reportType').value;let item=null;if(type!=='summary'){const ix=$('#reportRecord').value;if(ix==='')throw Error('Choose a saved product or decision for this report.');item=state[reportKinds[type][1]][Number(ix)];if(!item)throw Error('That saved record could not be found.')}const html=reportDocument(type,item),title=`${state.profile.name||'Business'} - ${type==='summary'?'Business Summary':reportKinds[type][0]}`;showResult(`<div class="report-actions"><button type="button" class="primary" id="print">Print / Save as PDF</button><button type="button" class="secondary" id="downloadPDF">Download PDF</button><button type="button" class="secondary" id="downloadReport">Save Report File</button></div>${html}<p class="muted">Download PDF creates a standalone PDF file without using the print dialog. Print is also available. Save Report File downloads an HTML copy that can be opened and printed later.</p>`);$('#print').onclick=()=>window.print();$('#downloadPDF').onclick=async()=>{const node=$('#printReport');const lines=[...node.querySelectorAll('h2,h3,p,tr')].map(x=>x.innerText.replace(/\s+/g,' ').trim()).filter(Boolean);try{await ToolkitPDF.download(title,lines,title.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.pdf')}catch(e){showResult(alert('PDF download failed: '+e.message,'error'))}};$('#downloadReport').onclick=()=>downloadReport(html,title)}catch(e){showResult(alert(e.message,'error'))}});

const updateHelp=()=>{if($('#helpResults'))$('#helpResults').innerHTML=helpResults($('#helpQuery')?.value||'',$('#helpCategory')?.value||'All topics')};$('#helpQuery')?.addEventListener('input',updateHelp);$('#helpCategory')?.addEventListener('change',updateHelp);
$('#saveTheme')?.addEventListener('click',()=>{const prev=state.theme;state.theme=$('#theme').value;if(!save()){state.theme=prev;message('#themeStatus',storageError,'error')}else{document.documentElement.style.setProperty('--accent',state.theme);message('#themeStatus','Theme saved.')}});
$('#portableExport')?.addEventListener('click',()=>{try{downloadJson(portableExport(),'business-numbers-toolkit-transfer-v1.json');message('#exportStatus','Transfer file prepared. Keep it somewhere safe.')}catch(e){message('#exportStatus','Could not create the transfer file: '+e.message,'error')}});
$('#transferImport')?.addEventListener('change',async e=>{try{const f=e.target.files?.[0];if(!f)return;if(f.size>15000000)throw Error('Transfer file is too large.');const data=JSON.parse(await f.text());const imported=ToolkitTransfer.parse(data);if(!confirm('Import this transfer file and replace the current Toolkit records? Download a backup first.'))return;const previous=state;state=normalize(imported);if(!save()){state=previous;throw Error(storageError)}render()}catch(err){message('#exportStatus','Import failed: '+err.message,'error')}});
$('#storageCheck')?.addEventListener('click',async()=>{try{const info=await ToolkitStorage.inspect();message('#settingsStatus',info?'Local database backup found, dated '+info.savedAt+'.':'No local database backup found.','warning')}catch(err){message('#settingsStatus','Database unavailable: '+err.message,'error')}});
$('#recoverDB')?.addEventListener('click',async()=>{try{const backup=await ToolkitStorage.inspect();if(!backup)throw Error('No recovery snapshot found.');if(!confirm('Replace current data with the local database snapshot from '+backup.savedAt+'? Download a backup first.'))return;const prev=state;state=normalize(backup.data);if(!save()){state=prev;throw Error(storageError)}render()}catch(err){message('#settingsStatus','Recovery failed: '+err.message,'error')}});

$('#backup')?.addEventListener('click',()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='business-numbers-toolkit-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)});
$('#restore')?.addEventListener('change',async e=>{try{const file=e.target.files?.[0];if(!file)return;const incoming=JSON.parse(await file.text());if(!incoming.profile||!Array.isArray(incoming.records))throw Error('Invalid toolkit backup.');if(!confirm('Replace all current toolkit data with this backup?'))return;const prev=state;state=normalize(incoming);if(!save()){state=prev;throw Error(storageError)}render()}catch(err){message('#settingsStatus','Restore failed: '+err.message,'error')}});
$('#reset')?.addEventListener('click',()=>{if(!confirm('Delete all toolkit data on this device? Download a backup first.'))return;const prev=state;state=empty();if(!save()){state=prev;message('#settingsStatus',storageError,'error')}else render()});
}
render();
bootStorage();
